#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    
    int t;
    cin>>t;
    
    while(t--)
    {
        int n;
        cin>>n;
        
        int m=3*n;
        
        vector<long long>ar(m);
        
        for(int i=0;i<m;i++)
        
            cin>>ar[i];
        sort(ar.rbegin(),ar.rend());
        vector<long long>pref(m+1,0);
        for(int i=0;i<m;i++)
        pref[i+1]=pref[i]+ar[i];
        long long res=LLONG_MIN;
        for(int k=0;k<=n;k++)
        {
            int l=0;
            int h=n-k;
            
            while(l<h)
            {
                int low=(l+h)/2;
                int p=k+2*low;
                int r=m-2*k-low;
                
                long long dif=ar[p]+ar[p+1]-3LL*ar[r-1];
                if(dif>=0)
            {
                l=low+1;
            }    
            else{
                h=low;
            }
            }
            
            for(int le=max(0,l-1);le<=min(n-k,l+1);le++)
            {
                int p=k+2*le;
                int r=m-2*k-le;
                
                long long curr=6LL*pref[k]+4LL*(pref[p]-pref[k])+3LL * (pref[r]-pref[p]);
                
                res=max(res,curr);
            }
        }
        cout<<res<<"\n";
        
        
            
        
    }
    return 0;
}
